<!doctype html><html><head><meta charset="utf-8"><title>Job Application Form</title><style>body{font:11px Arial;margin:0;padding:15px}.form{max-width:800px;margin:auto}.section{border:2px solid #000;margin-bottom:5px;padding:8px}.photo{float:right;width:70px;height:90px;border:1px solid #000;text-align:center}.main{margin-right:85px}.row{margin:6px 0}.label{font-weight:bold;font-size:10px}.line{border:0;border-bottom:1px solid #000;background:none}.tbl{width:100%;border-collapse:collapse;margin-top:5px}.tbl th,.tbl td{border:1px solid #000;padding:3px;text-align:center;font-size:9px}.tbl th{background:#f0f0f0}.title{font-weight:bold;font-size:12px;margin-bottom:5px}.sign{display:flex;justify-content:space-between;margin-top:20px}@media print{body{padding:10px}}</style></head><body><div class="form"><div class="section"><div style="text-align:center;font-weight:bold">PLEASE ANSWER EACH CLEARLY AND COMPLETELY. THE INFORMATION PROVIDED IN THIS<br>APPLICATION FORM WILL BE KEPT PRIVATE AND CONFIDENTIAL.</div><div class="photo"><?php if($application->photograph): ?><img src="<?php echo e(asset('uploads/job_photos/'.$application->photograph)); ?>" style="width:66px;height:86px;object-fit:cover"><?php else: ?> AFFIX<br>RECENT<br>PHOTOGRAPH<br>HERE <?php endif; ?></div><div class="main"><?php $__currentLoopData = [['1. Full Name','full_name'],["2. Father's/Husband Name",'father_husband_name'],['3. CNIC No.','cnic'],['4. Position Applied','position_applied'],['5. Min Salary Acceptable','min_salary_acceptable'],['6. Nationality','nationality'],['7. Religion','religion'],['8. Gender','gender'],['9. Height Ft','height_ft'],['9. Height Inches','height_inches'],['10. Weight Kg','weight_kg'],['13. Marital Status','marital_status'],['11. Date of Birth','date_of_birth'],['12. Place of Birth','place_of_birth'],['15. Contact No(s)','contact_numbers']]; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as [$label,$key]): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><div class="row"><span class="label"><?php echo e($label); ?>:</span> <input class="line" value="<?php echo e($key==='date_of_birth' ? $application->{$key}?->format('d/m/Y') : $application->{$key}); ?>" readonly style="width:220px"></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><div class="row"><span class="label">14. Mailing Address:</span><textarea readonly style="width:250px;height:35px"><?php echo e($application->mailing_address); ?></textarea></div></div></div><div class="section"><div class="title">16. QUALIFICATION</div><table class="tbl"><thead><tr><th>Sr.#</th><th>Level</th><th>Subjects</th><th>Institute</th><th>Session</th><th>Grade/Division</th><th>Marks in %</th><th>Office Use</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $application->qualifications??[]; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $i=>$q): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><?php echo e($i+1); ?></td><td><?php echo e($q['level']??''); ?></td><td><?php echo e($q['subjects']??''); ?></td><td><?php echo e($q['institute']??''); ?></td><td><?php echo e($q['session']??''); ?></td><td><?php echo e($q['grade']??''); ?></td><td><?php echo e($q['marks']??''); ?></td><td><?php echo e($q['office_use']??''); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?>@for($i=1;$i<=9;$i++)<tr><td><?php echo e($i); ?></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><?php endfor; ?> <?php endif; ?></tbody></table></div><div class="section"><div class="title">17. Previous Jobs</div><table class="tbl"><tr><th>Sr.#</th><th>Organization</th><th>Designation</th><th>Duration</th><th>Major Responsibilities</th></tr><?php $__empty_1 = true; $__currentLoopData = $application->previous_jobs??[]; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $i=>$j): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><?php echo e($i+1); ?></td><td><?php echo e($j['organization']??''); ?></td><td><?php echo e($j['designation']??''); ?></td><td><?php echo e($j['duration']??''); ?></td><td><?php echo e($j['responsibilities']??''); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="5" style="height:40px"></td></tr><?php endif; ?></table></div><div class="section"><div class="title">EXPERIENCE (Most Recent)</div><?php $__currentLoopData = $application->recent_experience??[]; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $i=>$e): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><p><b>Experience #<?php echo e($i+1); ?></b>: <?php echo e($e['company']??''); ?> | <?php echo e($e['joined_as']??''); ?> - <?php echo e($e['left_as']??''); ?> | <?php echo e($e['reason_to_leave']??''); ?> | <?php echo e($e['salary']??''); ?> | <?php echo e($e['reporting_to']??''); ?></p><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><div class="sign"><span>Applicant Signature: __________________</span><span>Date: __________________</span></div></div></body></html>
